     */
    func recall(key: String, backend: String?) throws  -> String?
    
    /**
     * `GET …/title` as a JSON object (404 before the first turn).
     */
    func titleJson() throws  -> String
    
    /**
     * `GET …/turns` as a JSON array.
     */
    func turnsJson() throws  -> String
    
}

